          <div className="border-t border-[#E4E4E7] dark:border-[#3F3F46] pt-2 flex justify-between font-bold">
            <span className="text-[#18181B] dark:text-[#F4F4F5]">Total</span>
            <span className="text-[#FF441F] text-lg">{fmt(total)}</span>
