404	              <div className="flex-shrink-0 text-right">
405	                <p className="text-sm font-bold text-[#18181B] dark:text-[#F4F4F5]">{fmt(item.unit_price * item.quantity)}</p>
406	                {item.quantity > 1 && <p className="text-[10px] text-[#71717A] dark:text-[#A1A1AA]">{fmt(item.unit_price)} cada</p>}
407	              </div>
408	            </div>
409	          ))}
410	          {/* Frete motoboy */}
