412	            <div className="flex items-center gap-1.5">
413	              <Icon name="Truck" size={13} className="text-[#71717A] dark:text-[#A1A1AA]" />
414	              <span className="text-sm text-[#71717A] dark:text-[#A1A1AA]">Frete motoboy</span>
