2159	  async getRelatorioGarcom(restaurantId: number, de: string, ate: string) {
2160	    const { data: garcons } = await this.supabase.client
2161	      .from('garcons')
2162	      .select('id, nome')
2163	      .eq('restaurant_id', restaurantId);
2164	
2165	    const { data: pedidos } = await this.supabase.client
2166	      .from('orders')
2167	      .select('id, total, status, canal, garcom_id, gorjeta_valor, created_at, numero_comanda, mesa_id, cliente_mesa_nome, customer_id, mesas(numero, nome), customers(name)')
2168	      .eq('restaurant_id', restaurantId)
2169	      .eq('canal', 'presencial')
2170	      .not('garcom_id', 'is', null)
2171	      .gte('created_at', de)
2172	      .lte('created_at', ate);
2173	
2174	    const orderIds = (pedidos ?? []).map((p: any) => p.id);
2175	    const { data: comissoes } = orderIds.length
2176	      ? await this.supabase.client
2177	          .from('garcom_comissoes_lancamentos')
2178	          .select('garcom_id, order_id, valor_calculado')
2179	          .in('order_id', orderIds)
2180	      : { data: [] as any[] };
2181	
2182	    const pagamentosPorComanda = await this.buscarPagamentosPorComanda(pedidos ?? []);
2183	
2184	    const { data: comandasAtuais } = await this.supabase.client
2185	      .from('orders')
2186	      .select('id, garcom_id, status')
2187	      .eq('restaurant_id', restaurantId)
2188	      .eq('canal', 'presencial')
2189	      .not('garcom_id', 'is', null)
2190	      .in('status', this.COMANDA_STATUS_ABERTOS);
2191	
2192	    const porGarcom = new Map<number, any>();
2193	    for (const g of (garcons ?? []) as any[]) {
2194	      porGarcom.set(g.id, {
2195	        garcom_id: g.id,
2196	        nome: g.nome,
2197	        total_vendido: 0,
2198	        total_comissao: 0,
2199	        total_gorjeta: 0,
2200	        comandas_abertas: 0,
2201	        comandas_pendentes: 0,
2202	      });
2203	    }
2204	
2205	    for (const p of (pedidos ?? []) as any[]) {
2206	      if (p.status !== 'paga') continue;
2207	      const row = porGarcom.get(p.garcom_id);
2208	      if (!row) continue;
2209	      row.total_vendido += p.total ?? 0;
2210	      row.total_gorjeta += p.gorjeta_valor ?? 0;
2211	    }
2212	
2213	    for (const c of (comissoes ?? []) as any[]) {
2214	      const row = porGarcom.get(c.garcom_id);
2215	      if (!row) continue;
2216	      row.total_comissao += c.valor_calculado ?? 0;
2217	    }
2218	
2219	    // Produto favorito de cada garçom: agrega quantidade/receita por produto entre as
2220	    // comandas pagas do período, reaproveitando o mesmo padrão de prodMap do getRelatorio.
2221	    const pedidosPagos = (pedidos ?? []).filter((p: any) => p.status === 'paga');
2222	    const garcomPorOrderId = new Map<number, number>(pedidosPagos.map((p: any) => [p.id, p.garcom_id]));
2223	    const orderIdsPagos = pedidosPagos.map((p: any) => p.id);
2224	    const { data: itemsGarcom } = orderIdsPagos.length
2225	      ? await this.supabase.client
2226	          .from('order_items')
2227	          .select('order_id, product_id, quantity, unit_price')
2228	          .in('order_id', orderIdsPagos)
2229	      : { data: [] as any[] };
2230	
2231	    const productIdsGarcom = [...new Set<number>((itemsGarcom ?? []).map((i: any) => i.product_id))];
2232	    const { data: produtosGarcom } = productIdsGarcom.length
2233	      ? await this.supabase.client.from('products').select('id, name').in('id', productIdsGarcom)
2234	      : { data: [] as any[] };
2235	    const prodNomeMap = Object.fromEntries((produtosGarcom ?? []).map((p: any) => [p.id, p.name]));
2236	
2237	    const produtosPorGarcom = new Map<number, Map<number, { name: string; quantidade: number; receita: number }>>();
2238	    for (const i of (itemsGarcom ?? []) as any[]) {
2239	      const garcomId = garcomPorOrderId.get(i.order_id);
2240	      if (!garcomId || !porGarcom.has(garcomId)) continue;
2241	      if (!produtosPorGarcom.has(garcomId)) produtosPorGarcom.set(garcomId, new Map());
2242	      const mapaProdutos = produtosPorGarcom.get(garcomId)!;
2243	      if (!mapaProdutos.has(i.product_id)) {
2244	        mapaProdutos.set(i.product_id, { name: prodNomeMap[i.product_id] ?? `#${i.product_id}`, quantidade: 0, receita: 0 });
2245	      }
2246	      const row = mapaProdutos.get(i.product_id)!;
2247	      row.quantidade += i.quantity ?? 0;
2248	      row.receita += (i.quantity ?? 0) * (i.unit_price ?? 0);
2249	    }
2250	    for (const [garcomId, mapaProdutos] of produtosPorGarcom) {
2251	      porGarcom.get(garcomId).produtos = [...mapaProdutos.values()]
2252	        .sort((a, b) => b.quantidade - a.quantidade)
2253	        .slice(0, 5);
2254	    }
2255	    for (const row of porGarcom.values()) {
2256	      if (!row.produtos) row.produtos = [];
2257	    }
2258	
2259	    for (const c of (comandasAtuais ?? []) as any[]) {
2260	      const row = porGarcom.get(c.garcom_id);
2261	      if (!row) continue;
2262	      if (c.status === 'aberta') row.comandas_abertas++;
2263	      if (c.status === 'fechada_garcom') row.comandas_pendentes++;
2264	    }
2265	
2266	    const { data: repasses } = await this.supabase.client
2267	      .from('garcom_repasses')
2268	      .select('id, garcom_id, valor_gorjeta, valor_comissao, pago_em')
2269	      .eq('restaurant_id', restaurantId)
2270	      .eq('periodo_de', de)
2271	      .eq('periodo_ate', ate);
2272	    const repassePorGarcom = new Map<number, any>((repasses ?? []).map((r: any) => [r.garcom_id, r]));
2273	    for (const row of porGarcom.values()) {
2274	      row.repasse = repassePorGarcom.get(row.garcom_id) ?? null;
2275	    }
2276	
2277	    const nomeGarcom = new Map<number, string>((garcons ?? []).map((g: any) => [g.id, g.nome]));
2278	    const vendas = (pedidos ?? [])
2279	      .filter((p: any) => p.status === 'paga')
2280	      .map((p: any) => {
2281	        const pagamentos = pagamentosPorComanda.get(p.id) ?? [];
2282	        const taxa_cartao = pagamentos.reduce((s, pg) => s + (pg.taxa_cartao_valor ?? 0), 0);
2283	        const formas_pagamento = pagamentos.length
2284	          ? [...new Set(pagamentos.map((pg) => pg.forma_pagamento))].join(' + ')
2285	          : null;
2286	        const gorjeta = p.gorjeta_valor ?? 0;
2287	        return {
2288	          order_id: p.id,
2289	          numero_comanda: p.numero_comanda,
2290	          garcom_id: p.garcom_id,
2291	          garcom_nome: nomeGarcom.get(p.garcom_id) ?? '—',
2292	          mesa_numero: p.mesas?.numero ?? null,
2293	          mesa_nome: p.mesas?.nome ?? null,
2294	          cliente_nome: p.customers?.name ?? p.cliente_mesa_nome ?? null,
2295	          data: p.created_at,
2296	          total: p.total ?? 0,
2297	          gorjeta,
2298	          taxa_cartao,
2299	          formas_pagamento,
2300	          total_geral: (p.total ?? 0) + gorjeta + taxa_cartao,
2301	        };
2302	      })
2303	      .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime());
2304	
2305	    // Sessões (turnos) de trabalho fechadas no período — pra tela do dono mostrar se o
2306	    // garçom já conferiu/aceitou os valores daquele intervalo (ver garcom-turno.service.ts).
2307	    const { data: turnos } = await this.supabase.client
2308	      .from('garcom_turnos')
2309	      .select('id, garcom_id, aberto_em, fechado_em, resumo, conferido_pelo_garcom, observacao_garcom')
2310	      .eq('restaurant_id', restaurantId)
2311	      .eq('status', 'fechado')
2312	      .gte('fechado_em', de)
2313	      .lte('fechado_em', ate)
2314	      .order('fechado_em', { ascending: false });
2315	
2316	    return { garcons: Array.from(porGarcom.values()), vendas, turnos: turnos ?? [] };
2317	  }
2318	
2319	  // Dono clica "Marcar como pago" na linha do garçom, pro período em foco no relatório —
2320	  // registra que a gorjeta + comissão calculadas ali já foram repassadas. UNIQUE
2321	  // (garcom_id, periodo_de, periodo_ate) impede marcar duas vezes o mesmo período.
2322	  async registrarRepasseGarcom(
2323	    restaurantId: number,
2324	    garcomId: number,
2325	    body: {
2326	      de: string; ate: string; valor_gorjeta: number; valor_comissao: number;
2327	      valor_dinheiro?: number; valor_pix?: number;
2328	    },
2329	  ) {
2330	    const { data: garcom } = await this.supabase.client
2331	      .from('garcons')
2332	      .select('id, nome')
2333	      .eq('id', garcomId)
2334	      .eq('restaurant_id', restaurantId)
2335	      .maybeSingle();
2336	    if (!garcom) throw new NotFoundException('Garçom não encontrado neste restaurante');
2337	
2338	    const total = Number((body.valor_gorjeta ?? 0) + (body.valor_comissao ?? 0));
2339	    const valorDinheiro = Number(body.valor_dinheiro ?? 0);
2340	    const valorPix = Number(body.valor_pix ?? 0);
2341	    if (Math.abs(valorDinheiro + valorPix - total) > 0.01) {
2342	      throw new BadRequestException('Soma dos valores por forma de pagamento não bate com o total a repassar');
2343	    }
2344	
2345	    // Repasse em dinheiro sai do caixa igual qualquer outra sangria — precisa de caixa
2346	    // aberto pra vincular a baixa. Repasse em PIX não mexe no caixa físico. Guarda
2347	    // caixa_id + criado_em da saída gerada pra dar pra estornar essa baixa específica
2348	    // depois, se o dono marcar o repasse como "não pago" de novo por engano.
2349	    let saidaCaixaId: number | null = null;
2350	    let saidaCriadoEm: string | null = null;
2351	    if (valorDinheiro > 0) {
2352	      const saida = await this.adicionarSaida(restaurantId, {
2353	        descricao: `Repasse gorjeta/comissão - ${garcom.nome}`,
2354	        valor: valorDinheiro,
2355	        meio: 'dinheiro',
2356	      });
2357	      saidaCaixaId = saida.caixa_id;
2358	      saidaCriadoEm = saida.criado_em;
2359	    }
2360	
2361	    const { data, error } = await this.supabase.client
2362	      .from('garcom_repasses')
2363	      .insert({
2364	        restaurant_id: restaurantId,
2365	        garcom_id: garcomId,
2366	        periodo_de: body.de,
2367	        periodo_ate: body.ate,
2368	        valor_gorjeta: body.valor_gorjeta ?? 0,
2369	        valor_comissao: body.valor_comissao ?? 0,
2370	        valor_dinheiro: valorDinheiro,
2371	        valor_pix: valorPix,
2372	        caixa_id: saidaCaixaId,
2373	        saida_criado_em: saidaCriadoEm,
2374	      })
2375	      .select('id, valor_gorjeta, valor_comissao, valor_dinheiro, valor_pix, pago_em')
2376	      .single();
